import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

@Controller('api/v1')
export class FnSfr01810Controller {
  @Post('/attendance-requests/:attendanceRequestId/submit')
  @HttpCode(200)
  async submitAttendanceRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const requestId = req.params['attendanceRequestId'];
    if (!/^[0-9]+$/.test(requestId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '근태 신청 번호가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT attendance_request_id AS "attendanceRequestId", attendance_type AS "attendanceType", reason AS "reason", approval_status AS "approvalStatus", approval_document_id AS "approvalDocumentId" FROM attendance_request WHERE attendance_request_id = CAST(:requestId AS bigint)',
        { requestId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'ATTENDANCE_REQUEST_NOT_FOUND', '근태 신청을 찾을 수 없습니다.');
      }
      const current = rows[0];
      // 전환표: 신청 상태이고 아직 결재 문서가 없는 건만 상신할 수 있다.
      if (current.approvalStatus !== '신청' || current.approvalDocumentId !== null) {
        throw new ApiError(409, 'ATTENDANCE_REQUEST_ALREADY_SUBMITTED', '이미 상신 또는 승인된 신청입니다.');
      }
      // 가정: 결재양식은 사용 중인 양식 중 가장 먼저 등록된 것을 쓴다.
      const forms = await db.query(
        "SELECT approval_form_id AS \"approvalFormId\" FROM approval_form WHERE use_status = '사용' ORDER BY approval_form_id LIMIT 1",
        {},
      );
      if (forms.length === 0) {
        throw new ApiError(502, 'APPROVAL_LINK_FAILED', '전자결재 양식이 없어 상신하지 못했습니다.');
      }
      // 가정: 문서번호는 신청 번호와 현재 시각으로 만든다.
      const docs = await db.query(
        "INSERT INTO approval_document (document_no, approval_form_id, drafter_id, title, body, approval_status, submitted_at, created_at, updated_at) VALUES ('ATT-' || :requestId || '-' || to_char(now(), 'YYYYMMDDHH24MISSMS'), CAST(:formId AS bigint), CAST(:userId AS bigint), :title, :body, '결재대기', now(), now(), now()) RETURNING approval_document_id AS \"approvalDocumentId\"",
        {
          requestId,
          formId: forms[0].approvalFormId,
          userId: user.id,
          title: '근태 신청 - ' + current.attendanceType,
          body: current.reason,
        },
      );
      const approvalDocumentId = docs[0].approvalDocumentId;
      await db.execute(
        'UPDATE attendance_request SET approval_document_id = CAST(:documentId AS bigint), updated_at = now() WHERE attendance_request_id = CAST(:requestId AS bigint)',
        { documentId: approvalDocumentId, requestId },
      );
      return { approvalDocumentId };
    });
  }
}

