import { useState } from 'react';
import {
  Band,
  Badge,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  ErrorText,
  Field,
  Filters,
  Form,
  Pager,
  Select,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const TYPES: [string, string][] = [
  ['출장', '출장'],
  ['외근', '외근'],
];
const STATUSES: [string, string][] = [
  ['신청', '신청'],
  ['마감', '마감'],
  ['마감 취소', '마감 취소'],
  ['승인', '승인'],
  ['승인 취소', '승인 취소'],
  ['반려', '반려'],
];
const SIZE = 20;

export default function FnSfr01810Page({ role, notify }: PageProps) {
  const [typeFilter, setTypeFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [query, setQuery] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [creating, setCreating] = useState(false);
  const [target, setTarget] = useState<Row | null>(null);
  const [form, setForm] = useState<Row>({});

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/attendance-requests', role, undefined, { ...query, page, size: SIZE }),
    [role, query, page],
  );

  function search() {
    setPage(0);
    setQuery({ attendanceType: typeFilter, approvalStatus: statusFilter });
  }

  function reset() {
    setTypeFilter('');
    setStatusFilter('');
    setPage(0);
    setQuery({});
  }

  function openCreate() {
    setForm({ attendanceType: '출장' });
    setCreating(true);
  }

  async function create() {
    if (!form.attendanceType || !form.startDate || !form.endDate) {
      throw new Error('근태 유형, 시작일, 종료일을 입력해 주세요.');
    }
    await call('POST', '/attendance-requests', role, {
      attendanceType: form.attendanceType,
      startDate: form.startDate,
      endDate: form.endDate,
      reason: form.reason,
      changedWorkTime: form.changedWorkTime,
    });
    notify('출장·외근 신청을 등록했습니다.');
    setCreating(false);
    reload();
  }

  async function submit() {
    if (!target) return;
    await call('POST', `/attendance-requests/${target.attendanceRequestId}/submit`, role);
    notify('결재 상신했습니다.');
    setTarget(null);
    reload();
  }

  return (
    <div>
      <h1>출장 및 외근 관리</h1>
      <Filters onSearch={search} onReset={reset}>
        <Field label='근태 유형'>
          <Select value={typeFilter} onChange={setTypeFilter} options={TYPES} placeholder='전체' />
        </Field>
        <Field label='승인 처리 상태'>
          <Select value={statusFilter} onChange={setStatusFilter} options={STATUSES} placeholder='전체' />
        </Field>
      </Filters>
      <Band total={data?.total}>
        <button onClick={openCreate}>출장·외근 신청</button>
      </Band>
      {error ? <ErrorText text={error} /> : null}
      <DataTable
        rows={data?.items ?? []}
        empty='아직 등록한 신청 내역이 없습니다. 출장·외근 신청 버튼으로 등록해 주세요.'
        columns={[
          { key: 'attendanceType', label: '근태 유형' },
          { key: 'startDate', label: '시작일', render: (r) => <DateText value={r.startDate} /> },
          { key: 'endDate', label: '종료일', render: (r) => <DateText value={r.endDate} /> },
          { key: 'approvalStatus', label: '승인 처리 상태', render: (r) => <Badge value={r.approvalStatus} /> },
          {
            key: 'action',
            label: '처리',
            render: (r) =>
              r.approvalStatus === '신청' ? (
                <button className='ghost' onClick={() => setTarget(r)}>
                  결재 상신
                </button>
              ) : null,
          },
        ]}
      />
      <Pager page={data?.page ?? 0} size={SIZE} total={data?.total ?? 0} onPage={setPage} />
      {creating ? (
        <Drawer title='출장·외근 신청' onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit='등록'>
            <Field label='근태 유형' required>
              <Select value={form.attendanceType} onChange={(v) => setForm({ ...form, attendanceType: v })} options={TYPES} />
            </Field>
            <Field label='시작일' required>
              <DateInput value={form.startDate} onChange={(v) => setForm({ ...form, startDate: v })} />
            </Field>
            <Field label='종료일' required>
              <DateInput value={form.endDate} onChange={(v) => setForm({ ...form, endDate: v })} />
            </Field>
            <Field label='사유' wide>
              <TextInput multiline value={form.reason} onChange={(v) => setForm({ ...form, reason: v })} />
            </Field>
            <Field label='변경 근무시간'>
              <TextInput value={form.changedWorkTime} onChange={(v) => setForm({ ...form, changedWorkTime: v })} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {target ? (
        <Drawer title='결재 상신' onClose={() => setTarget(null)}>
          <Form
            onSubmit={submit}
            submit='결재 상신'
            note='상신하면 전자결재 문서가 만들어지며, 승인된 뒤에는 임의로 수정하거나 삭제할 수 없습니다.'
          >
            <p>
              {String(target.attendanceType)} 신청(<DateText value={target.startDate} /> ~ <DateText value={target.endDate} />)을 결재 상신합니다.
            </p>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
